contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint value) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(value > 0);
        require(address(this).balance >= value);

        uint cBalBefore = address(c).balance;
        uint testBalBefore = address(this).balance;

        require(cBalBefore >= value);

        c.withdraw(value); if (__ESBMC_reverted()) return;

        uint cBalAfter = address(c).balance;
        uint testBalAfter = address(this).balance;

        assert(cBalBefore - cBalAfter == value && testBalAfter - testBalBefore == value);
    }

    receive() external payable {}
}

