// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 value) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(value > 0);
        vm.assume(address(this).balance >= value);
        uint cBalBefore = address(c).balance;
        uint testBalBefore = address(this).balance;
        vm.assume(cBalBefore >= value);
        try c.withdraw(value) {} catch { return; }
        uint cBalAfter = address(c).balance;
        uint testBalAfter = address(this).balance;
        assertTrue(cBalBefore - cBalAfter == value && testBalAfter - testBalBefore == value);
    }

    function testFuzz_run(uint256 value) public {
        _run(value);
    }

    receive() external payable {}
}
